pub mod arc_core;
pub mod camera;
pub mod lighting;
pub mod scene;
pub mod ui;
use bevy::prelude::*;
use bevy_arc_studio::{arc_core::*, camera::EditorCameraPlugin, lighting::LightingPlugin, scene::ScenePlugin, ui::UiPlugin};
use bevy_egui::EguiPlugin;

fn main() {
    let preset = std::env::args().nth(1).and_then(|a| match a.as_str() {
        "dusk" => Some(WorldPreset::MistyDuskLake),
        "noon" => Some(WorldPreset::SunnyAlpineNoon),
        "night" => Some(WorldPreset::MidnightCampfire),
        "dawn" => Some(WorldPreset::GoldenAutumnDawn),
        _ => None,
    });
    let spec = preset.map(WorldSpec::from_preset).unwrap_or_default();
    App::new()
        .add_plugins(DefaultPlugins.set(WindowPlugin {
            primary_window: Some(Window { title: "Bevy ArcStudio".into(), resolution: (1600, 900).into(), ..default() }),
            ..default()
        }))
        .add_plugins(EguiPlugin::default())
        .add_plugins(bevy_brp_extras::BrpExtrasPlugin::default())
        .insert_resource(spec)
        .insert_resource(UndoHistory::<WorldSpec>::default())
        .register_type::<WorldSpec>()
        .add_plugins((ScenePlugin, EditorCameraPlugin, LightingPlugin, UiPlugin))
        .run();
}
//! Startup scene: terrain mesh, water, scatter props, camp fire, camera and sun entities.

use bevy::asset::RenderAssetUsages;
use bevy::light::atmosphere::ScatteringMedium;
use bevy::light::{FogVolume, SunDisk, VolumetricLight};
use bevy::mesh::{Indices, PrimitiveTopology};
use bevy::prelude::*;

use crate::arc_core::*;
use crate::camera::EditorCamera;
use crate::lighting::{self, Moon, NightLight, Sun};

#[derive(Resource)]
pub struct TerrainGrid(pub HeightfieldGrid);

pub struct ScenePlugin;

impl Plugin for ScenePlugin {
    fn build(&self, app: &mut App) {
        app.add_systems(Startup, setup_scene);
    }
}

pub fn build_terrain_mesh(g: &HeightfieldGrid, splats: &[Splat]) -> Mesh {
    let n = g.n;
    let mut pos = Vec::with_capacity(n * n);
    let mut nrm = Vec::with_capacity(n * n);
    let mut col = Vec::with_capacity(n * n);
    for j in 0..n {
        for i in 0..n {
            let (x, z) = g.grid_to_world(i, j);
            pos.push([x, g.heights[g.idx(i, j)], z]);
            nrm.push(g.sample_normal(x, z).to_array());
            let s = &splats[g.idx(i, j)];
            col.push([s.albedo[0], s.albedo[1], s.albedo[2], 1.0]);
        }
    }
    let mut idx = Vec::with_capacity((n - 1) * (n - 1) * 6);
    for j in 0..n - 1 {
        for i in 0..n - 1 {
            let (a, b, c, d) = ((j * n + i) as u32, (j * n + i + 1) as u32, ((j + 1) * n + i) as u32, ((j + 1) * n + i + 1) as u32);
            idx.extend_from_slice(&[a, c, b, b, c, d]);
        }
    }
    Mesh::new(PrimitiveTopology::TriangleList, RenderAssetUsages::default())
        .with_inserted_attribute(Mesh::ATTRIBUTE_POSITION, pos)
        .with_inserted_attribute(Mesh::ATTRIBUTE_NORMAL, nrm)
        .with_inserted_attribute(Mesh::ATTRIBUTE_COLOR, col)
        .with_inserted_indices(Indices::U32(idx))
}

fn setup_scene(
    mut commands: Commands,
    spec: Res<WorldSpec>,
    mut meshes: ResMut<Assets<Mesh>>,
    mut mats: ResMut<Assets<StandardMaterial>>,
    mut media: ResMut<Assets<ScatteringMedium>>,
) {
    let mut grid = HeightfieldGrid::generate(&spec);
    grid.erode_hydraulic(spec.erosion_droplets, spec.seed as u64);
    grid.erode_thermal(spec.thermal_iterations, 35.0);
    grid.clamp_heights(spec.max_height);
    let splats = grid.build_splatmap(&spec);

    commands.spawn((
        Name::new("Terrain"),
        Mesh3d(meshes.add(build_terrain_mesh(&grid, &splats))),
        MeshMaterial3d(mats.add(StandardMaterial { base_color: Color::WHITE, perceptual_roughness: 0.85, reflectance: 0.25, ..default() })),
    ));
    commands.spawn((
        Name::new("Water"),
        Mesh3d(meshes.add(Plane3d::default().mesh().size(grid.size, grid.size))),
        Transform::from_xyz(0.0, spec.water_level, 0.0),
        MeshMaterial3d(mats.add(StandardMaterial {
            base_color: Color::srgba(0.05, 0.16, 0.22, 0.92),
            perceptual_roughness: 0.04,
            reflectance: 0.7,
            alpha_mode: AlphaMode::Blend,
            ..default()
        })),
    ));

    spawn_scatter(&mut commands, &spec, &grid, &mut meshes, &mut mats);

    commands.spawn((
        Name::new("Sun"),
        Sun,
        DirectionalLight { shadow_maps_enabled: spec.shadows, illuminance: 100_000.0, ..default() },
        SunDisk::EARTH,
        VolumetricLight,
        lighting::cascades(),
        Transform::default().looking_to(Vec3::NEG_Y, Vec3::X),
    ));
    commands.spawn((
        Name::new("Moon"),
        Moon,
        DirectionalLight { color: Color::srgb(0.55, 0.65, 1.0), illuminance: 0.0, shadow_maps_enabled: false, ..default() },
        Transform::default().looking_to(Vec3::NEG_Y, Vec3::X),
    ));
    commands.spawn((
        Name::new("FogVolume"),
        FogVolume { density_factor: 0.02, scattering: 0.4, absorption: 0.05, ..default() },
        Transform::from_xyz(0.0, 40.0, 0.0).with_scale(Vec3::new(grid.size, 120.0, grid.size)),
    ));

    let camp = Vec3::new(spec.camp_center[0], grid.sample_height(spec.camp_center[0], spec.camp_center[1]), spec.camp_center[1]);
    let medium = media.add(ScatteringMedium::earth(256, 256));
    commands.spawn((
        Name::new("EditorCamera"),
        Camera3d::default(),
        EditorCamera { pivot: camp + Vec3::new(-14.0, 2.0, 8.0), distance: 34.0, yaw: -1.2, pitch: 0.14, ..default() },
        Transform::default(),
        lighting::camera_stack(&spec, medium),
    ));
    commands.insert_resource(TerrainGrid(grid));
}

fn spawn_scatter(commands: &mut Commands, spec: &WorldSpec, grid: &HeightfieldGrid, meshes: &mut Assets<Mesh>, mats: &mut Assets<StandardMaterial>) {
    let mut mat = |c: Color, r: f32| mats.add(StandardMaterial { base_color: c, perceptual_roughness: r, ..default() });
    let (bark, needles, needles2) = (mat(Color::srgb(0.22, 0.14, 0.08), 0.9), mat(Color::srgb(0.05, 0.20, 0.09), 0.85), mat(Color::srgb(0.07, 0.25, 0.10), 0.85));
    let rock = mat(Color::srgb(0.30, 0.30, 0.32), 0.8);
    let grass = mat(Color::srgb(0.20, 0.38, 0.10), 0.9);
    let reed = mat(Color::srgb(0.45, 0.50, 0.22), 0.8);
    let wood = mat(Color::srgb(0.38, 0.26, 0.15), 0.8);
    let tent = mat(Color::srgb(0.75, 0.38, 0.12), 0.8);
    let fire = mats.add(StandardMaterial { base_color: Color::srgb(1.0, 0.45, 0.1), emissive: LinearRgba::rgb(40.0, 14.0, 2.0), ..default() });

    let trunk_m = meshes.add(Cylinder::new(0.22, 2.0));
    let cone_m = meshes.add(Cone::new(1.6, 3.4));
    let cone2_m = meshes.add(Cone::new(1.15, 3.0));
    let rock_m = meshes.add(Sphere::new(1.0).mesh().ico(2).unwrap());
    let grass_m = meshes.add(Cone::new(0.18, 0.7));
    let reed_m = meshes.add(Cylinder::new(0.03, 1.8));
    let plank_m = meshes.add(Cuboid::new(2.6, 0.12, 0.9));
    let log_m = meshes.add(Cylinder::new(0.25, 1.8));
    let tent_m = meshes.add(Cone::new(1.9, 2.0).mesh().resolution(4));
    let fire_m = meshes.add(Sphere::new(0.28));

    for it in generate_scatter_plan(spec, grid) {
        let tf = Transform { translation: it.pos, rotation: it.rot, scale: Vec3::splat(it.scale) };
        match it.kind {
            ScatterKind::Pine => {
                commands.spawn((Name::new("Pine"), tf, Visibility::default())).with_children(|c| {
                    c.spawn((Mesh3d(trunk_m.clone()), MeshMaterial3d(bark.clone()), Transform::from_xyz(0.0, 1.0, 0.0)));
                    c.spawn((Mesh3d(cone_m.clone()), MeshMaterial3d(needles.clone()), Transform::from_xyz(0.0, 3.2, 0.0)));
                    c.spawn((Mesh3d(cone2_m.clone()), MeshMaterial3d(needles2.clone()), Transform::from_xyz(0.0, 5.3, 0.0)));
                });
            }
            ScatterKind::Boulder => {
                commands.spawn((Name::new("Boulder"), Mesh3d(rock_m.clone()), MeshMaterial3d(rock.clone()), tf.with_scale(Vec3::new(1.2, 0.8, 1.0) * it.scale)));
            }
            ScatterKind::Grass => {
                commands.spawn((Mesh3d(grass_m.clone()), MeshMaterial3d(grass.clone()), tf * Transform::from_xyz(0.0, 0.3, 0.0)));
            }
            ScatterKind::Reed => {
                commands.spawn((Mesh3d(reed_m.clone()), MeshMaterial3d(reed.clone()), tf * Transform::from_xyz(0.0, 0.8, 0.0)));
            }
            ScatterKind::PierPlank => {
                commands.spawn((Name::new("PierPlank"), Mesh3d(plank_m.clone()), MeshMaterial3d(wood.clone()), tf));
            }
            ScatterKind::Log => {
                commands.spawn((
                    Name::new("Log"),
                    Mesh3d(log_m.clone()),
                    MeshMaterial3d(wood.clone()),
                    tf * Transform::from_xyz(0.0, 0.25, 0.0).with_rotation(Quat::from_rotation_z(std::f32::consts::FRAC_PI_2)),
                ));
            }
            ScatterKind::Tent => {
                commands.spawn((
                    Name::new("Tent"),
                    Mesh3d(tent_m.clone()),
                    MeshMaterial3d(tent.clone()),
                    tf * Transform::from_xyz(0.0, 1.0, 0.0).with_rotation(Quat::from_rotation_y(std::f32::consts::FRAC_PI_4)),
                ));
            }
            ScatterKind::Campfire => {
                commands.spawn((Name::new("Campfire"), Mesh3d(fire_m.clone()), MeshMaterial3d(fire.clone()), tf * Transform::from_xyz(0.0, 0.3, 0.0))).with_children(|c| {
                    c.spawn((
                        NightLight { base: 90_000.0 },
                        PointLight { color: Color::srgb(1.0, 0.55, 0.22), intensity: 0.0, range: 45.0, radius: 0.3, shadow_maps_enabled: true, ..default() },
                        Transform::from_xyz(0.0, 0.9, 0.0),
                    ));
                });
            }
        }
    }
}
//! AAA atmosphere: physical sky, sun/moon cycle, volumetric fog, SSR, bloom, night fires.

use bevy::camera::Exposure;
use bevy::core_pipeline::tonemapping::Tonemapping;
use bevy::light::atmosphere::ScatteringMedium;
use bevy::light::{
    Atmosphere, AtmosphereEnvironmentMapLight, CascadeShadowConfig, CascadeShadowConfigBuilder, DirectionalLightShadowMap, GlobalAmbientLight, VolumetricFog,
    VolumetricLight,
};
use bevy::pbr::{AtmosphereSettings, DistanceFog, FogFalloff, ScreenSpaceReflections};
use bevy::post_process::bloom::Bloom;
use bevy::prelude::*;

use crate::arc_core::{QualityPreset, WorldSpec, smoothstep};

#[derive(Component)]
pub struct Sun;
#[derive(Component)]
pub struct Moon;
/// Point light that is lit between dusk and dawn (19:30–06:30).
#[derive(Component)]
pub struct NightLight {
    pub base: f32,
}

const SUN_AZIMUTH: f32 = 0.6;
const EV_DAY: f32 = 13.5;
const EV_NIGHT: f32 = 5.5;

/// Unit vector pointing from the scene towards the sun.
pub fn sun_direction(t: f32) -> Vec3 {
    let a = (t - 6.0) / 24.0 * std::f32::consts::TAU;
    Vec3::new(a.cos() * SUN_AZIMUTH.cos(), a.sin(), a.cos() * SUN_AZIMUTH.sin()).normalize()
}

/// 0 = night, 1 = full day (smooth through twilight).
pub fn daylight(t: f32) -> f32 {
    smoothstep(-0.12, 0.28, sun_direction(t).y)
}

/// 1 when night lights should burn: 19:30 → 06:30 with 30 min fades.
pub fn night_factor(t: f32) -> f32 {
    let t = t.rem_euclid(24.0);
    if t >= 12.0 { smoothstep(19.25, 19.75, t) } else { 1.0 - smoothstep(6.25, 6.75, t) }
}

pub fn cascades() -> CascadeShadowConfig {
    CascadeShadowConfigBuilder { num_cascades: 4, minimum_distance: 0.5, maximum_distance: 220.0, first_cascade_far_bound: 12.0, overlap_proportion: 0.3 }.build()
}

fn fog_component(spec: &WorldSpec) -> DistanceFog {
    DistanceFog {
        color: Color::linear_rgb(spec.fog_color[0], spec.fog_color[1], spec.fog_color[2]),
        directional_light_color: Color::srgba(1.0, 0.75, 0.45, 0.4),
        directional_light_exponent: 30.0,
        falloff: FogFalloff::Exponential { density: spec.fog_density },
    }
}

/// All render components on the 3D camera.
pub fn camera_stack(spec: &WorldSpec, medium: Handle<ScatteringMedium>) -> impl Bundle {
    (
        Msaa::Off,
        Tonemapping::TonyMcMapface,
        Exposure { ev100: EV_DAY },
        Atmosphere::earth(medium),
        AtmosphereSettings::default(),
        AtmosphereEnvironmentMapLight::default(),
        (
            Bloom::NATURAL,
            ScreenSpaceReflections::default(),
            VolumetricFog { ambient_intensity: 0.0, step_count: 48, ..default() },
            fog_component(spec),
        ),
    )
}

pub struct LightingPlugin;

impl Plugin for LightingPlugin {
    fn build(&self, app: &mut App) {
        app.insert_resource(GlobalAmbientLight { color: Color::srgb(0.45, 0.55, 0.9), brightness: 0.0, ..default() })
            .insert_resource(DirectionalLightShadowMap { size: 4096 })
            .add_systems(Update, (advance_clock, apply_time_of_day, apply_toggles, flicker_night_lights).chain());
    }
}

fn advance_clock(mut spec: ResMut<WorldSpec>, time: Res<Time>) {
    if spec.auto_sun {
        spec.time_of_day = (spec.time_of_day + time.delta_secs() * 0.15).rem_euclid(24.0);
    }
}

#[allow(clippy::type_complexity)]
fn apply_time_of_day(
    spec: Res<WorldSpec>,
    mut sun: Query<(&mut Transform, &mut DirectionalLight), (With<Sun>, Without<Moon>)>,
    mut moon: Query<(&mut Transform, &mut DirectionalLight), (With<Moon>, Without<Sun>)>,
    mut cam: Query<(&mut Exposure, &mut DistanceFog)>,
    mut ambient: ResMut<GlobalAmbientLight>,
) {
    let t = spec.time_of_day;
    let dir = sun_direction(t);
    let d = daylight(t);
    let elev = dir.y;
    if let Ok((mut tf, mut l)) = sun.single_mut() {
        *tf = Transform::default().looking_to(-dir, Vec3::Y);
        l.illuminance = 130_000.0 * spec.sun_intensity * smoothstep(-0.04, 0.12, elev);
        l.shadow_maps_enabled = spec.shadows && elev > -0.03;
    }
    if let Ok((mut tf, mut l)) = moon.single_mut() {
        let mdir = Vec3::new(-dir.x, dir.y.abs().max(0.35), -dir.z).normalize();
        *tf = Transform::default().looking_to(-mdir, Vec3::Y);
        l.illuminance = 22.0 * (1.0 - d);
        l.shadow_maps_enabled = spec.shadows && d < 0.3;
    }
    let ev = EV_NIGHT + (EV_DAY - EV_NIGHT) * d.powf(0.8);
    ambient.brightness = 14.0 * (1.0 - d);
    for (mut exp, mut fog) in &mut cam {
        exp.ev100 = ev;
        let vis = smoothstep(-0.25, 0.3, elev);
        let k = 0.015 + 0.985 * vis;
        let dusk = (1.0 - (elev.abs() * 4.0).min(1.0)) * vis; // warm tint near the horizon
        let c = Vec3::from(spec.fog_color) * k + Vec3::new(0.35, 0.12, -0.05) * dusk * 0.5;
        fog.color = Color::linear_rgb(c.x.max(0.0), c.y.max(0.0), c.z.max(0.0));
        fog.directional_light_color = Color::srgba(1.0, 0.75, 0.45, 0.4 * smoothstep(0.0, 0.2, elev));
        fog.falloff = FogFalloff::Exponential { density: if spec.fog_enabled { spec.fog_density } else { 0.0 } };
    }
}

/// Feature toggles & quality preset → add/remove camera components.
fn apply_toggles(
    spec: Res<WorldSpec>,
    mut commands: Commands,
    cam: Query<Entity, With<Camera3d>>,
    sun: Query<Entity, With<Sun>>,
    mut shadow_map: ResMut<DirectionalLightShadowMap>,
) {
    if !spec.is_changed() {
        return;
    }
    shadow_map.size = match spec.quality_preset {
        QualityPreset::Low => 1024,
        QualityPreset::Medium => 2048,
        QualityPreset::High => 4096,
        QualityPreset::Ultra => 8192,
    };
    for e in &cam {
        let mut c = commands.entity(e);
        if spec.bloom { c.insert(Bloom::NATURAL); } else { c.remove::<Bloom>(); }
        if spec.reflections { c.insert(ScreenSpaceReflections::default()); } else { c.remove::<ScreenSpaceReflections>(); }
        if spec.god_rays { c.insert(VolumetricFog { ambient_intensity: 0.0, step_count: 48, ..default() }); } else { c.remove::<VolumetricFog>(); }
    }
    for e in &sun {
        if spec.god_rays { commands.entity(e).insert(VolumetricLight); } else { commands.entity(e).remove::<VolumetricLight>(); }
    }
}

fn flicker_night_lights(spec: Res<WorldSpec>, time: Res<Time>, mut q: Query<(&NightLight, &mut PointLight)>) {
    let n = night_factor(spec.time_of_day);
    let t = time.elapsed_secs();
    let f = 1.0 + 0.10 * (t * 17.0).sin() * (t * 5.3).cos() + 0.05 * (t * 41.0).sin();
    for (nl, mut l) in &mut q {
        l.intensity = nl.base * n * f;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn night_window_matches_spec() {
        assert_eq!(night_factor(12.0), 0.0);
        assert_eq!(night_factor(19.0), 0.0);
        assert_eq!(night_factor(20.0), 1.0);
        assert_eq!(night_factor(3.0), 1.0);
        assert_eq!(night_factor(7.0), 0.0);
        assert!(sun_direction(12.0).y > 0.99 && sun_direction(0.0).y < -0.99);
        assert!(daylight(12.0) > 0.99 && daylight(0.0) < 0.01);
    }
}
//! Minimal egui panel: world presets, atmosphere toggles, transactional undo/redo.

use bevy::prelude::*;
use bevy_egui::{EguiContexts, EguiPrimaryContextPass, egui};

use crate::arc_core::*;

pub struct UiPlugin;

impl Plugin for UiPlugin {
    fn build(&self, app: &mut App) {
        app.add_systems(EguiPrimaryContextPass, studio_ui_system);
    }
}

fn studio_ui_system(mut contexts: EguiContexts, mut spec: ResMut<WorldSpec>, mut hist: ResMut<UndoHistory<WorldSpec>>) {
    let Ok(ctx) = contexts.ctx_mut() else { return };
    let mut viewport_ui = egui::Ui::new(ctx.clone(), "viewport".into(), egui::UiBuilder::new().layer_id(egui::LayerId::background()).max_rect(ctx.viewport_rect()));
    egui::Panel::left("studio_panel").default_size(250.0).show(&mut viewport_ui, |ui| {
        ui.heading("Bevy ArcStudio");
        ui.horizontal(|ui| {
            if ui.add_enabled(hist.undo_len() > 0, egui::Button::new("Undo")).clicked() {
                if let Some(s) = hist.undo() {
                    *spec = s;
                }
            }
            if ui.add_enabled(hist.redo_len() > 0, egui::Button::new("Redo")).clicked() {
                if let Some(s) = hist.redo() {
                    *spec = s;
                }
            }
            ui.label(format!("{}/{}", hist.undo_len(), hist.redo_len()));
        });
        ui.separator();
        for (name, p) in [
            ("Misty Dusk Lake", WorldPreset::MistyDuskLake),
            ("Sunny Alpine Noon", WorldPreset::SunnyAlpineNoon),
            ("Midnight Campfire", WorldPreset::MidnightCampfire),
            ("Golden Autumn Dawn", WorldPreset::GoldenAutumnDawn),
        ] {
