/// Perlin fBm (value ≈ [-1,1]).
fn fbm(noise: &noise::Perlin, x: f64, y: f64, octaves: u32) -> f32 {
    use noise::NoiseFn;
    let (mut sum, mut amp, mut freq, mut norm) = (0.0, 1.0, 1.0, 0.0);
    for _ in 0..octaves {
        sum += amp * noise.get([x * freq, y * freq]);
        norm += amp;
        amp *= 0.5;
        freq *= 2.0;
    }
    (sum / norm) as f32
}

