input.command:
mkdir -p assets/models && python - <<'EOF'
import re
p='src/arc_core.rs'
s=open(p,encoding='utf-8').read()
s=s.replace("""    PierPlank,
    Campfire,
    Log,
    Tent,
}""","""    /// Wooden pier: `pos` = shore end (deck height), local +X runs towards the lake, `scale` = length in metres.
    WoodenPier,
    /// Fire ring, logs, benches and tent around the camp centre.
    CampfireSite,
}""")
a=s.index("    // pier: planks")
b=s.index("    items\n}\n",a)
new='''    // pier: from the camp-side shore towards the lake centre until the water is deep enough
    let to_camp = (camp - lake).normalize_or_zero();
    let dir = if to_camp == Vec2::ZERO { Vec2::X } else { to_camp };
    let heading = -dir; // lake centre direction
    let mut shore: Option<f32> = None;
    let mut s = spec.lake_radius * 1.8;
    let mut end = None;
    while s > 0.0 {
        let p = lake + dir * s;
        let d = grid.sample_height(p.x, p.y) - spec.water_level;
        if shore.is_none() && d < 0.35 {
            shore = Some(s);
        }
        if let Some(s0) = shore {
            if d < -1.8 || s0 - s > 18.0 {
                end = Some(s);
                break;
            }
        }
        s -= 0.5;
    }
    if let (Some(s0), Some(s1)) = (shore, end) {
        let p = lake + dir * (s0 + 1.2); // start slightly on land
        let yaw = dir.y.atan2(-dir.x);
        let _ = heading;
        items.push(ScatterItem { kind: ScatterKind::WoodenPier, pos: Vec3::new(p.x, spec.water_level + 0.55, p.y), rot: Quat::from_rotation_y(yaw), scale: (s0 - s1 + 1.2).max(5.0) });
    }

    // camp site (one composite prefab)
    let cy = grid.sample_height(camp.x, camp.y);
    items.push(ScatterItem { kind: ScatterKind::CampfireSite, pos: Vec3::new(camp.x, cy, camp.y), rot: Quat::IDENTITY, scale: 1.0 });
'''
s=s[:a]+new+s[b:]
s=s.replace("i.kind == ScatterKind::Campfire)","i.kind == ScatterKind::CampfireSite)")
s=s.replace("s.time_of_day = 19.0;","s.time_of_day = 20.8;").replace("s.time_of_day = 12.0;","s.time_of_day = 13.5;")
open(p,'w',encoding='utf-8').write(s)
EOF
grep -n "heading" src/arc_core.rs

